insert into deadline_private.roles(case_slug,slot,content) values
('demo-v1',1,'{"name":"Alex Berg","occupation":"Affärspartner","background":"Du och Johan drev ett projekt tillsammans. Johan ville avsluta samarbetet i kväll.","knows":"Du har passerkort A7. Bara du använde det i kväll.","secret":"Du är mördaren. Du gick in i arkivet 21.12 och lämnade det 21.18.","objective":"Undvik att bli utpekad. Du får ljuga om ditt alibi, men inte förfalska eller gömma gemensamma bevis.","is_murderer":true,"rules":"Läs inte upp hela kortet. Du får undanhålla din hemlighet. Gemensamma bevis får aldrig ändras eller gömmas. Följ undantaget i ditt mål när du ljuger."}'::jsonb),
('demo-v1',2,'{"name":"Robin Ek","occupation":"Ekonomiansvarig","background":"Du kontrollerar projektets ekonomi och grälade med Johan om ett försvunnet kvitto.","knows":"Du var i stora salen med Sam från 21.10 till 21.20.","secret":"Du slarvade bort kvittot och försökte dölja det.","objective":"Hitta mördaren utan att ditt slarv tar över diskussionen.","is_murderer":false,"rules":"Läs inte upp hela kortet. Du får undanhålla din hemlighet men inte hitta på fakta eller ändra det du sett. Gemensamma bevis får aldrig ändras eller gömmas."}'::jsonb),
('demo-v1',3,'{"name":"Sam Lind","occupation":"Fotograf","background":"Du dokumenterade kvällens evenemang. Johan ville inte att en viss bild skulle publiceras.","knows":"Du fotograferade Robin i stora salen 21.14.","secret":"Du behöll bilden trots Johans protester. Den visar ett gräl före mordet.","objective":"Hitta mördaren och förklara vad ditt fotografi faktiskt visar.","is_murderer":false,"rules":"Läs inte upp hela kortet. Du får undanhålla din hemlighet men inte hitta på fakta eller ändra det du sett. Gemensamma bevis får aldrig ändras eller gömmas."}'::jsonb),
('demo-v1',4,'{"name":"Kim Dahl","occupation":"Assistent","background":"Du planerade kvällen och hittade Johan i arkivet 21.20.","knows":"Arkivets nödutgång är larmad. Huvudingången registrerar varje passage.","secret":"Du läste ett privat brev där Johan avslutade ett affärssamarbete.","objective":"Hitta mördaren. Du väljer när du berättar om brevet.","is_murderer":false,"rules":"Läs inte upp hela kortet. Du får undanhålla din hemlighet men inte hitta på fakta eller ändra det du sett. Gemensamma bevis får aldrig ändras eller gömmas."}'::jsonb),
('demo-v1',5,'{"name":"Liv Strand","occupation":"Trädgårdsansvarig","background":"Du kom till festen efter ditt arbetspass.","knows":"Du såg Johan och Alex diskutera häftigt strax före klockan 21.","secret":"Du hade bett Johan om ett förskott på din ersättning.","objective":"Hitta mördaren och skilj på ekonomiska problem och bevis.","is_murderer":false,"rules":"Läs inte upp hela kortet. Du får undanhålla din hemlighet men inte hitta på fakta eller ändra det du sett. Gemensamma bevis får aldrig ändras eller gömmas."}'::jsonb),
('demo-v1',6,'{"name":"Charlie Nord","occupation":"Evenemangsansvarig","background":"Du ansvarade för gästlistan.","knows":"Robin och Sam stod tillsammans i stora salen under en del av kvällen.","secret":"Du släppte in en gäst utan biljett tidigare under dagen.","objective":"Hitta mördaren utan att ditt misstag förväxlas med mordet.","is_murderer":false,"rules":"Läs inte upp hela kortet. Du får undanhålla din hemlighet men inte hitta på fakta eller ändra det du sett. Gemensamma bevis får aldrig ändras eller gömmas."}'::jsonb),
('demo-v1',7,'{"name":"Lo West","occupation":"Säkerhetsansvarig","background":"Du ansvarade för passerkorten under evenemanget.","knows":"Varje gäst tilldelades ett personligt passerkort. Den skriftliga listan är mer pålitlig än ditt minne.","secret":"Du kom sent till morgonmötet och ville inte berätta det.","objective":"Hitta mördaren med hjälp av loggarna, inte rykten.","is_murderer":false,"rules":"Läs inte upp hela kortet. Du får undanhålla din hemlighet men inte hitta på fakta eller ändra det du sett. Gemensamma bevis får aldrig ändras eller gömmas."}'::jsonb),
